 interest charge\" for \"Public debt\" column\n\nt = [0, 1, 2, 3, 4, 5, 6]  # FY 1961 to FY 1967 (t=0 in FY 1961)\ny = [3072, 3239, 3360, 3560, 3678, 3988, 4039]  # in millions\n\nprint(\"Data points:\")\nfor ti, yi in zip(t, y):\n    print(f\"  t={ti} (FY {1961+ti}): {yi} million\")\n\n# OLS regression: y = a + b*t\nn = len(t)\nsum_t = sum(t)\nsum_y = sum(y)\nsum_tt = sum(ti**2 for ti in t)\nsum_ty = sum(ti * yi for ti, yi in zip(t, y))\n\n# Calculate slope (b) and intercept (a)\nb = (n * sum_ty - sum_t * sum_y) / (n * sum_tt - sum_t**2)\na = (sum_y - b * sum_t) / n\n\nprint(f\"\\nOLS Regression: y = {a:.4f} + {b:.4f} * t\")\nprint(f\"Intercept (a): {a:.4f}\")\nprint(f\"Slope (b): {b:.4f}\")\n\n# Predict FY 1968 (t=7)\nt_1968 = 7\ny_pred_1968 = a + b * t_1968\nprint(f\"\\nPredicted FY 1968 (t={t_1968}): {y_pred_1968:.4f} million\")\n\n# Actual FY 1968\nactual_1968 = 4499\nprint(f\"Actual FY 1968: {actual_1968} million\")\n\n# Forecast error\nforecast_error = y_pred_1968 - actual_1968\nprint(f\"\\nForecast error = {forecast_error:.4f} million\")\nprint(f\"Forecast error (rounded to nearest hundredths): {round(forecast_error, 2)} million\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
